// txt::stencil: a shape read once and written many times.
//
// Three things are checked here. That the syntax means what Go's
// text/template means by it, which is what stencil_tests.h holds — the
// oracle, generated by tools/stencil_oracle.go, over one shape of data
// built the same way on both sides. That a value written with a
// specification after the colon comes out exactly as txt::format writes
// it with the same specification, which is the whole of why this lives
// in txt and not somewhere of its own: the test asks format.h the same
// question and compares, so the two cannot drift. And that a source
// nobody meant is refused with a place and a reason rather than
// crashing, which is what the fuzzer at the end is for.
#include "tests/types.h"
#include "tests/txt/stencil_tests.h"

// Directly, and not through txt.h: the module's own header takes this in
// once the name of the type is settled, and the line that goes there is
// in .agent/template.md
#include "sgcl/txt/stencil.h"

#include <chrono>
#include <cstdio>
#include <random>
#include <string>
#include <vector>

namespace {
    // The same shape of data tools/stencil_oracle.go builds, field for
    // field: the oracle's answers are only worth anything if the
    // question is the same one.
    txt::value oracle_data() {
        return txt::object{
            {"name", "ada lovelace"},
            {"spaced", "  Countess  "},
            {"admin", true},
            {"guest", false},
            {"n", 42},
            {"zero", 0},
            {"pi", 3.14159},
            {"whole", 88.0},
            {"empty", ""},
            {"tags", txt::list{"one", "two", "three"}},
            {"nolist", txt::list{}},
            {"user", txt::object{{"first", "ada"}, {"last", "lovelace"}}},
            {"rows", txt::list{
                txt::object{{"who", "ada"}, {"on", true}},
                txt::object{{"who", "bob"}, {"on", false}},
            }},
        };
    }

    string render(const char* source, const txt::value& data) {
        auto t = txt::stencil::parse(string(source));
        EXPECT_TRUE(t.has_value()) << "did not parse: " << source;
        if (!t) {
            return string();
        }
        return t->render(data);
    }

    // The error of a source that is refused, nothing for one that parses
    sgcl::optional<txt::stencil_error> refusal(const char* source) {
        auto t = txt::stencil::parse(string(source));
        if (t) {
            return sgcl::nullopt;
        }
        return t.error();
    }
}

//------------------------------------------------------------------------------
// The oracle
//------------------------------------------------------------------------------
TEST(StencilTest, MatchesGoOverTheSharedSyntax) {
    auto data = oracle_data();
    size_t asked = 0;
    for (auto& c : oracle::GoTemplateTests) {
        auto t = txt::stencil::parse(string(c.source));
        ASSERT_TRUE(t.has_value())
            << "did not parse: " << c.source << " (" << t.error().message() << ")";
        auto got = t->render(data);
        EXPECT_EQ(std::string(got.data(), got.size()), std::string(c.want))
            << "over: " << c.source;
        ++asked;
    }
    // The oracle having quietly become empty would make every assertion
    // above pass and mean nothing
    EXPECT_GT(asked, 40u);
}

//------------------------------------------------------------------------------
// The value, and how a template reads it
//------------------------------------------------------------------------------
TEST(StencilTest, ValueHoldsTheSevenShapes) {
    EXPECT_EQ(txt::value().kind(), txt::value_kind::none);
    EXPECT_EQ(txt::value(nullptr).kind(), txt::value_kind::none);
    EXPECT_EQ(txt::value(true).kind(), txt::value_kind::boolean);
    EXPECT_EQ(txt::value(42).kind(), txt::value_kind::integer);
    EXPECT_EQ(txt::value(42u).kind(), txt::value_kind::integer);
    EXPECT_EQ(txt::value(42LL).kind(), txt::value_kind::integer);
    EXPECT_EQ(txt::value(1.5).kind(), txt::value_kind::real);
    EXPECT_EQ(txt::value(1.5f).kind(), txt::value_kind::real);
    EXPECT_EQ(txt::value("x").kind(), txt::value_kind::text);
    EXPECT_EQ(txt::value(string("x")).kind(), txt::value_kind::text);
    EXPECT_EQ(txt::list{1}.kind(), txt::value_kind::list);
    EXPECT_EQ(txt::object{}.kind(), txt::value_kind::object);

    // A value is the size of a string and a tag, and nothing about a
    // number or a truth is allocated
    EXPECT_LE(sizeof(txt::value), 32u);
}

TEST(StencilTest, TruthIsTheRuleEveryoneExpects) {
    EXPECT_FALSE(txt::value().truthy());
    EXPECT_FALSE(txt::value(false).truthy());
    EXPECT_FALSE(txt::value(0).truthy());
    EXPECT_FALSE(txt::value(0.0).truthy());
    EXPECT_FALSE(txt::value("").truthy());
    EXPECT_FALSE(txt::list{}.truthy());
    EXPECT_FALSE(txt::object{}.truthy());
    EXPECT_TRUE(txt::value(true).truthy());
    EXPECT_TRUE(txt::value(1).truthy());
    EXPECT_TRUE(txt::value(-1).truthy());
    EXPECT_TRUE(txt::value(0.5).truthy());
    EXPECT_TRUE(txt::value("x").truthy());
    EXPECT_TRUE(txt::list{0}.truthy());
    EXPECT_TRUE((txt::object{{"a", 1}}).truthy());
}

TEST(StencilTest, BracesNestWithoutNamingATypeEveryTime) {
    // A list inside a mapping needs no type named at all, the braces
    // being unambiguous where the element is a value
    auto data = txt::object{
        {"tags", {"one", "two"}},
        {"deep", txt::object{{"inner", {1, 2, 3}}}},
    };
    EXPECT_EQ(render("{{range .tags}}{{.}} {{end}}", data), "one two ");
    EXPECT_EQ(render("{{range .deep.inner}}{{.}}{{end}}", data), "123");
}

TEST(StencilTest, AMappingKeepsTheOrderItWasWrittenIn) {
    // Not the order of a hash: a page written twice running must be the
    // same page
    auto data = txt::object{
        {"m", txt::object{{"zz", 1}, {"aa", 2}, {"mm", 3}}},
    };
    auto once = render("{{range .m}}{{.key}}={{.value}} {{end}}", data);
    auto twice = render("{{range .m}}{{.key}}={{.value}} {{end}}", data);
    EXPECT_EQ(once, "zz=1 aa=2 mm=3 ");
    EXPECT_EQ(once, twice);
}

TEST(StencilTest, ObjectIsBuiltAFieldAtATimeToo) {
    txt::object o;
    o.set("a", 1);
    o.set("b", "two");
    o.set("a", 3);                  // replaces, and keeps its place
    EXPECT_EQ(render("{{.a}}/{{.b}}", o), "3/two");
}

//------------------------------------------------------------------------------
// What the module is for: the value is written by format.h
//------------------------------------------------------------------------------
TEST(StencilTest, ASpecificationMeansWhatFormatMeansByIt) {
    // The point of the header, asked directly: whatever stands after the
    // colon in a field must write exactly what txt::format writes with
    // the same specification. If this ever drifts, two implementations
    // of writing a number have grown where there should be one.
    auto data = txt::object{
        {"n", 42},
        {"d", 3.14159},
        {"s", "zaba"},
        {"neg", -7},
    };
    EXPECT_EQ(render("{{.n:>8}}", data), txt::format("{:>8}", 42));
    EXPECT_EQ(render("{{.n:*^9}}", data), txt::format("{:*^9}", 42));
    EXPECT_EQ(render("{{.n:#x}}", data), txt::format("{:#x}", 42));
    EXPECT_EQ(render("{{.n:#06b}}", data), txt::format("{:#06b}", 42));
    EXPECT_EQ(render("{{.n:+}}", data), txt::format("{:+}", 42));
    EXPECT_EQ(render("{{.neg:08}}", data), txt::format("{:08}", -7));
    EXPECT_EQ(render("{{.d:>8.2f}}", data), txt::format("{:>8.2f}", 3.14159));
    EXPECT_EQ(render("{{.d:.3e}}", data), txt::format("{:.3e}", 3.14159));
    EXPECT_EQ(render("{{.s:>10}}", data), txt::format("{:>10}", string("zaba")));
    EXPECT_EQ(render("{{.s:.2}}", data), txt::format("{:.2}", string("zaba")));
    EXPECT_EQ(render("{{.s:?}}", data), txt::format("{:?}", string("zaba")));
}

TEST(StencilTest, AFieldOfTextIsMeasuredInColumnsAndNotInBytes) {
    // The other half of why this is here. "zolc" with the Polish
    // letters is eight bytes and four columns, so a field of ten pads it
    // by six; a precision stops on a code point and never in the middle
    // of one.
    string polish = "żółć";
    EXPECT_EQ(polish.size(), 8u);
    auto data = txt::object{{"s", polish}};
    EXPECT_EQ(render("[{{.s:>10}}]", data), txt::format("[{:>10}]", polish));
    EXPECT_EQ(render("[{{.s:>10}}]", data).size(), 8u + 6u + 2u);
    EXPECT_EQ(render("{{.s:.2}}", data), txt::format("{:.2}", polish));
    // The debug form quotes and escapes, and a width over it is over
    // what comes out
    EXPECT_EQ(render("[{{.s:>8?}}]", data), txt::format("[{:>8?}]", polish));
}

TEST(StencilTest, AListAndAMappingComeOutInTheShapesOfCxx23) {
    // Nothing here writes a bracket: the range and pair formatters of
    // format.h do it, reached through a formatter<value>
    auto data = txt::object{
        {"xs", txt::list{1, 2, 3}},
        {"ws", txt::list{"a, b"}},
        {"m", txt::object{{"a", 1}}},
    };
    EXPECT_EQ(render("{{.xs}}", data), "[1, 2, 3]");
    EXPECT_EQ(render("{{.xs::>4}}", data), "[   1,    2,    3]");
    EXPECT_EQ(render("{{.xs:n}}", data), "1, 2, 3");
    // The elements of a list are written the way a program would write
    // them, so one holding a comma is not two
    EXPECT_EQ(render("{{.ws}}", data), "[\"a, b\"]");
    EXPECT_EQ(render("{{.m}}", data), "{\"a\": 1}");
    // And the same value handed to format directly writes the same
    EXPECT_EQ(render("{{.xs}}", data), txt::format("{}", data.find("xs") ? *data.find("xs") : txt::value()));
}

TEST(StencilTest, ASpecificationTheValueRefusesKeepsTheField) {
    // The one thing that cannot be settled where the source is read: the
    // type the field will meet. {:d} over a name is that case, and the
    // answer is to drop the letter and keep the column rather than to
    // lose the value or refuse the page.
    auto data = txt::object{{"s", "ada"}, {"n", 42}};
    EXPECT_EQ(render("[{{.s:>6d}}]", data), "[   ada]");
    EXPECT_EQ(render("[{{.n:>6s}}]", data), "[    42]");
    // And a specification the value does take is honoured whole
    EXPECT_EQ(render("[{{.n:>6d}}]", data), "[    42]");
}

TEST(StencilTest, ACharacterFieldIsACodePointAndNeverThrows) {
    // The one road that could take a page down with it. format.h narrows
    // {:c} to a char and throws over a number no char holds — the value
    // being what is wrong there, and a pattern's caller being present to
    // catch it. A template has no such caller: the number comes from the
    // data and the letter from a file somebody edited, and the two never
    // meet until the page is rendered. So here it is a code point, and a
    // number that is none of them drops the letter like every other
    // specification a value will not take.
    auto data = txt::object{
        {"a", 65},          // A
        {"e", 233},         // e with an acute, two bytes of UTF-8
        {"cjk", 12345},     // past anything a byte holds
        {"top", 0x10FFFF},  // the last code point there is
        {"neg", -1},
        {"past", 0x110000},
        {"surrogate", 0xD800},
    };
    EXPECT_EQ(render("{{.a:c}}", data), "A");
    // Not the byte 0xE9, which is no character at all: this module's
    // text is UTF-8 and value(char) is refused for that very reason
    EXPECT_EQ(render("{{.e:c}}", data), "é");
    EXPECT_EQ(render("{{.e:c}}", data).size(), 2u);
    EXPECT_EQ(render("{{.cjk:c}}", data), txt::format("{:c}", char32_t(12345)));
    EXPECT_EQ(render("{{.top:c}}", data), txt::format("{:c}", char32_t(0x10FFFF)));
    // and every page that comes out of it is text a reader can read
    EXPECT_TRUE(utf8::valid(render("{{.e:c}}", data).view()));
    EXPECT_TRUE(utf8::valid(render("{{.cjk:c}}", data).view()));
    // The numbers that are no code point: the letter goes, the field stays
    EXPECT_EQ(render("[{{.neg:c}}]", data), "[-1]");
    EXPECT_EQ(render("[{{.neg:>6c}}]", data), "[    -1]");
    EXPECT_EQ(render("[{{.past:c}}]", data), "[1114112]");
    EXPECT_EQ(render("[{{.surrogate:c}}]", data), "[55296]");
    // and the same through render_to, which is the other road
    auto t = txt::stencil::parse(string("{{.cjk:c}}{{.neg:c}}"));
    ASSERT_TRUE(t.has_value());
    char room[64];
    EXPECT_GT(t->render_to(slice<char>(room, sizeof room), data), 0u);
}

TEST(StencilTest, AFieldMadeOfFieldsIsWrittenOnceAtEveryLevel) {
    // A thing made of other things in a field has to be written before
    // it can be told how wide it came out, and what stood there wrote it
    // twice: once to be counted and once to be kept. Over a value made
    // of values that is not a constant — a list inside a list inside a
    // list, each of them in a field of its own — because every level
    // doubles the level below it. Twenty-four levels came to 947 ms for
    // a page of fifty characters, exactly two to the power of the depth,
    // out of a template of a hundred characters. One walk and the shape
    // is the depth.
    txt::value v(7);
    std::string spec = ">2";
    for (int i = 0; i < 24; ++i) {
        vector<txt::value> one;
        one.push_back(v);
        v = txt::list(one);
        spec += ":>2";
    }
    std::string src = "{{ v:" + spec + " }}";
    auto t = txt::stencil::parse(string(src.c_str()));
    ASSERT_TRUE(t.has_value());
    auto data = txt::object{{"v", v}};
    auto started = std::chrono::steady_clock::now();
    auto page = t->render(data);
    auto took = std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now() - started).count();
    EXPECT_LT(took, 100.0) << "twenty-four levels took " << took << " ms";
    // and the page is the one it always was: every level a bracket, the
    // seven at the bottom, and every field padded to two
    EXPECT_EQ(page.size(), 50u);
    EXPECT_EQ(page.view().substr(0, 3), "[[[");
    EXPECT_NE(page.view().find(" 7"), std::string_view::npos);
}

TEST(StencilTest, AFieldMadeOfLargeFieldsIsWrittenOnceAtEveryLevel) {
    // The same nest with forty numbers beside the list at every level,
    // three hundred and twenty bytes of them, so that every level is
    // bigger than a field's first room. That was the shape still left
    // over from the one above: a level that outgrew 256 bytes was
    // written again, with everything under it, and sixteen levels of
    // three hundred bytes came to 443 ms. The levels share their room
    // now and grow it for one another, and the same page is 0.17 ms.
    vector<txt::value> forty;
    std::string numbers = "[";
    for (int i = 0; i < 40; ++i) {
        forty.push_back(txt::value(123456 + i));
        numbers += (i ? ", " : "") + std::to_string(123456 + i);
    }
    numbers += "]";
    txt::value v(7);
    std::string spec = ">2";
    for (int i = 0; i < 16; ++i) {
        vector<txt::value> two;
        two.push_back(txt::list(forty));
        two.push_back(v);
        v = txt::list(two);
        spec += ":>2";
    }
    auto t = txt::stencil::parse(string(("{{ v:" + spec + " }}").c_str()));
    ASSERT_TRUE(t.has_value());
    auto data = txt::object{{"v", v}};
    auto started = std::chrono::steady_clock::now();
    auto page = t->render(data);
    auto took = std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now() - started).count();
    EXPECT_LT(took, 100.0) << "sixteen large levels took " << took << " ms";
    // Every level is its forty numbers, a comma and the level under it,
    // and the fields are too narrow to pad anything but the seven
    std::string want = " 7";
    for (int i = 0; i < 16; ++i) {
        want = "[" + numbers + ", " + want + "]";
    }
    EXPECT_EQ(std::string(page.view()), want);
    // and a field wide enough to pad the outermost
    auto wide = txt::stencil::parse(string(("{{ v:*<9000" + spec.substr(2) + " }}").c_str()));
    ASSERT_TRUE(wide.has_value());
    auto padded = wide->render(data);
    ASSERT_LT(want.size(), 9000u);
    EXPECT_EQ(std::string(padded.view()), want + std::string(9000 - want.size(), '*'));
}

TEST(StencilTest, AValueThatHoldsItselfIsWrittenAndNotFollowedForever) {
    // The two compound shapes reach their elements through a tracked
    // pointer, so a mapping can be put inside itself with no cast and no
    // trick: the second value shares the pointer of the first. The
    // collector is happy with the cycle; the writer has no memory of
    // where it has been, and used to walk it until the stack ran out.
    txt::object o;
    o.set("name", "ada");
    o.set("self", o);               // the same value_object, now inside itself
    auto page = render("{{.}}", o);
    EXPECT_GT(page.size(), 0u);
    EXPECT_NE(page.view().find("ada"), std::string_view::npos);
    EXPECT_NE(page.view().find("..."), std::string_view::npos);
    // and the same value handed to format directly
    EXPECT_EQ(txt::format("{}", txt::value(o)), page);
    // twice running is the same page: the count is given back on the way out
    EXPECT_EQ(render("{{.}}", o), page);
    // a list that holds itself, and one that holds a mapping that holds it
    vector<txt::value> ring;
    ring.push_back(txt::value(1));
    txt::list l(ring);
    txt::object holder;
    holder.set("in", l);
    EXPECT_GT(render("{{.}}", holder).size(), 0u);
    // through a pipeline, which writes the value into text of its own
    EXPECT_GT(render("{{. | upper}}", o).size(), 0u);
    // and through render_to, into room too small for any of it
    auto t = txt::stencil::parse(string("{{.}}"));
    ASSERT_TRUE(t.has_value());
    char room[8];
    EXPECT_EQ(t->render_to(slice<char>(room, sizeof room), o), page.size());

    // A tree that is deep but not a ring is written whole, right up to
    // the last level the walk allows
    txt::value deep(7);
    for (int i = 0; i < 60; ++i) {
        vector<txt::value> one;
        one.push_back(deep);
        deep = txt::list(one);
    }
    auto whole = render("{{.}}", deep);
    EXPECT_NE(whole.view().find('7'), std::string_view::npos);
    EXPECT_EQ(whole.view().find("..."), std::string_view::npos);
}

TEST(StencilTest, AWidthNoFieldCouldHaveIsRefusedWhereTheSourceIsRead) {
    // The specification after the colon is read by format.h's own
    // reader, so a template gets the same bound a pattern does — and it
    // needs it more. A pattern is a literal of the program; a source is
    // a file somebody edited, and sixteen characters of it used to ask
    // render for a page of four thousand million bytes.
    auto why = refusal("{{ n:>4294967295 }}");
    ASSERT_TRUE(why);
    EXPECT_EQ(why->message(), "that is not a specification");
    EXPECT_TRUE(refusal("{{ n:>65536 }}"));
    // and the last width there is still parses and still pads
    auto data = txt::object{{"n", 1}};
    EXPECT_EQ(render("{{ n:>65535 }}", data).size(), 65535u);
}

TEST(StencilTest, ANameTheDataDoesNotCarryWritesNothingButKeepsItsField) {
    auto data = txt::object{{"a", 1}};
    EXPECT_EQ(render("[{{.missing}}]", data), "[]");
    EXPECT_EQ(render("[{{.missing:>5}}]", data), "[     ]");
    EXPECT_EQ(render("[{{.a.deeper.still}}]", data), "[]");
    EXPECT_EQ(render("{{if .missing}}yes{{else}}no{{end}}", data), "no");
}

//------------------------------------------------------------------------------
// The pipeline
//------------------------------------------------------------------------------
TEST(StencilTest, TheCaseFunctionsAreTheFullMappingsOfTheModule) {
    // Not a cheaper rule than case.h has: one letter may become two, and
    // this is exactly where the oracle could not follow
    auto data = txt::object{
        {"s", "straße"},
        {"p", "żółć"},
    };
    EXPECT_EQ(render("{{.s | upper}}", data), txt::to_upper_full(string("straße")));
    EXPECT_EQ(render("{{.s | upper}}", data), "STRASSE");
    EXPECT_EQ(render("{{.p | upper}}", data), txt::to_upper_full(string("żółć")));
    EXPECT_EQ(render("{{.p | upper | lower}}", data), "żółć");
}

TEST(StencilTest, EscapeHtmlIsAskedForByNameAndNeverGiven) {
    auto data = txt::object{{"h", "<a href=\"x\">R&D's</a>"}, {"plain", "nothing here"}};
    EXPECT_EQ(render("{{.h | escape_html}}", data),
              "&lt;a href=&quot;x&quot;&gt;R&amp;D&#39;s&lt;/a&gt;");
    // The boundary written down: without the function nothing is
    // escaped, because this module does not know where a value lands
    EXPECT_EQ(render("{{.h}}", data), "<a href=\"x\">R&D's</a>");
    // Text with nothing to escape comes back as it was
    EXPECT_EQ(render("{{.plain | escape_html}}", data), "nothing here");
}

TEST(StencilTest, AFunctionOfTheCallersJoinsTheOthers) {
    txt::stencil_functions table;           // starts with the six
    table.add("repeat", [](const txt::value& v, slice<const txt::value> args) {
        long long n = args.empty() ? 2 : 0;
        if (!args.empty()) {
            auto t = args[0].to_string();
            n = std::atoll(std::string(t.data(), t.size()).c_str());
        }
        std::string room;
        auto one = v.to_string();
        for (long long i = 0; i < n; ++i) {
            room.append(one.data(), one.size());
        }
        return txt::value(string(room.data(), room.size()));
    });
    // One of the six replaced by a name of the caller's
    table.add("upper", [](const txt::value& v, slice<const txt::value>) {
        return txt::value(string("<") + v.to_string() + string(">"));
    });

    auto data = txt::object{{"s", "ab"}};
    auto t = txt::stencil::parse(string("{{.s | repeat 3}}|{{.s | upper}}"), table);
    ASSERT_TRUE(t.has_value());
    EXPECT_EQ(t->render(data), "ababab|<ab>");

    // And the table the template was given is the one it uses: the
    // built-in upper is untouched
    EXPECT_EQ(render("{{.s | upper}}", data), "AB");
}

TEST(StencilTest, AStageWithNoArgumentsIsGivenNoneAndBuildsNoRoomForThem) {
    // The road five of the six built-in functions take. A stage written
    // no arguments skips the room a stage with them needs, so what it is
    // handed has to be an empty slice and not a slice over eight values
    // that happen to hold nothing.
    txt::stencil_functions table;
    size_t seen = size_t(-1);
    bool had_data = true;
    table.add("look", [&](const txt::value& v, slice<const txt::value> args) {
        seen = args.size();
        had_data = args.data() != nullptr;
        return v;
    });
    auto data = txt::object{{"s", "ab"}};

    auto none = txt::stencil::parse(string("{{.s | look}}"), table);
    ASSERT_TRUE(none.has_value());
    EXPECT_EQ(none->render(data), "ab");
    EXPECT_EQ(seen, 0u);
    EXPECT_FALSE(had_data);

    // and one that was written arguments still gets them, in order
    table.add("look", [&](const txt::value& v, slice<const txt::value> args) {
        seen = args.size();
        string made = v.to_string();
        for (auto& a : args) {
            made = made + string("/") + a.to_string();
        }
        return txt::value(made);
    });
    auto some = txt::stencil::parse(string("{{.s | look 1 \"x\" 2.5}}"), table);
    ASSERT_TRUE(some.has_value());
    EXPECT_EQ(some->render(data), "ab/1/x/2.5");
    EXPECT_EQ(seen, 3u);

    // two stages of one field, the first with none and the second with one
    auto both = txt::stencil::parse(string("{{.s | upper | look \"z\"}}"), table);
    ASSERT_TRUE(both.has_value());
    EXPECT_EQ(both->render(data), "AB/z");
}

TEST(StencilTest, AFunctionNobodyWroteIsRefusedWhereTheSourceIsRead) {
    // Not at render, when whoever could fix it is no longer looking
    auto why = refusal("{{.a | nosuchfunction}}");
    ASSERT_TRUE(why);
    EXPECT_EQ(why->message(), "no function of that name");
}

TEST(StencilTest, LiteralsGoDownThePipeToo) {
    auto data = txt::object{{"a", 0}, {"s", ""}};
    EXPECT_EQ(render("{{.a | default \"none\"}}", data), "none");
    EXPECT_EQ(render("{{.a | default 5}}", data), "5");
    EXPECT_EQ(render("{{.a | default -5}}", data), "-5");
    EXPECT_EQ(render("{{.a | default 1.5}}", data), "1.5");
    EXPECT_EQ(render("{{.s | default \"a\\nb\"}}", data), "a\nb");
    EXPECT_EQ(render("{{.s | default 'x'}}", data), "x");
    // A literal standing where a value would, which is also the only way
    // to write a brace that opens nothing
    EXPECT_EQ(render("{{ \"{{\" }}not an action", data), "{{not an action");
}

TEST(StencilTest, ADefaultTakesTheValueWhereThereIsOne) {
    auto data = txt::object{{"n", 7}, {"s", "x"}, {"t", true}, {"f", false}};
    EXPECT_EQ(render("{{.n | default 0}}", data), "7");
    EXPECT_EQ(render("{{.s | default \"y\"}}", data), "x");
    EXPECT_EQ(render("{{.t | default \"y\"}}", data), "true");
    EXPECT_EQ(render("{{.f | default \"y\"}}", data), "y");
}

//------------------------------------------------------------------------------
// The syntax this has that the oracle could not be asked about
//------------------------------------------------------------------------------
TEST(StencilTest, ABareNameIsAFieldOfTheDot) {
    // The one place the syntax departs from Go on purpose: over there a
    // name with no dot is a function call, here it is the shorthand
    // every other template language has
    auto data = txt::object{
        {"a", 1},
        {"u", txt::object{{"b", 2}}},
        {"xs", txt::list{"p", "q"}},
    };
    EXPECT_EQ(render("{{a}}", data), "1");
    EXPECT_EQ(render("{{.a}}", data), "1");
    EXPECT_EQ(render("{{u.b}}", data), "2");
    EXPECT_EQ(render("{{range xs}}{{.}}{{end}}", data), "pq");
    EXPECT_EQ(render("{{if a}}y{{end}}", data), "y");
    EXPECT_EQ(render("{{with u}}{{b}}{{end}}", data), "2");
    // and the two ways read the same
    EXPECT_EQ(render("{{u.b}}", data), render("{{.u.b}}", data));
}

TEST(StencilTest, TheRootIsReachableFromAnyDepth) {
    auto data = txt::object{
        {"top", "T"},
        {"xs", txt::list{txt::list{1, 2}, txt::list{3}}},
    };
    EXPECT_EQ(render("{{range xs}}{{range .}}{{.}}{{$.top}} {{end}}{{end}}", data),
              "1T 2T 3T ");
    // $ alone is the whole of the data
    EXPECT_EQ(render("{{range xs}}{{$.top}}{{end}}", data), "TT");
}

TEST(StencilTest, ADotAloneIsTheElement) {
    auto data = txt::object{{"xs", txt::list{1, 2}}};
    EXPECT_EQ(render("{{range xs}}[{{.}}]{{end}}", data), "[1][2]");
    EXPECT_EQ(render("{{range xs}}[{{.:>4}}]{{end}}", data), "[   1][   2]");
    EXPECT_EQ(render("{{range xs}}[{{ . :>4}}]{{end}}", data), "[   1][   2]");
}

TEST(StencilTest, BlocksNestAsDeepAsTheSourceGoes) {
    auto data = txt::object{
        {"xs", txt::list{
            txt::object{{"on", true}, {"ys", txt::list{1, 2}}},
            txt::object{{"on", false}, {"ys", txt::list{3}}},
        }},
    };
    EXPECT_EQ(render("{{range xs}}{{if on}}{{range ys}}{{.}}{{end}}{{else}}-{{end}}{{end}}", data),
              "12-");
    // with inside range inside with
    auto deep = txt::object{{"a", txt::object{{"xs", txt::list{txt::object{{"b", txt::object{{"c", "z"}}}}}}}}};
    EXPECT_EQ(render("{{with a}}{{range xs}}{{with b}}{{c}}{{end}}{{end}}{{end}}", deep), "z");
}

TEST(StencilTest, NestingPastTheRoomOnTheStackStillWorks) {
    // A render keeps its frames, its dots and its owned values on the
    // stack while the blocks are shallow and moves them to vectors past
    // that. The second road is the one nothing else here walks, so it is
    // walked on purpose: twelve blocks deep, where the room on the stack
    // holds four.
    std::string source;
    std::string want;
    txt::value data = txt::object{{"xs", txt::list{1, 2}}};
    for (int i = 0; i < 12; ++i) {
        source += "{{range $.xs}}";
    }
    source += "x";
    for (int i = 0; i < 12; ++i) {
        source += "{{end}}";
    }
    auto t = txt::stencil::parse(string(source.data(), source.size()));
    ASSERT_TRUE(t.has_value());
    // two elements, twelve deep
    want.assign(size_t(1) << 12, 'x');
    auto page = t->render(data);
    EXPECT_EQ(std::string(page.data(), page.size()), want);

    // And the same depth in `with`, which keeps one value per block
    std::string nest;
    for (int i = 0; i < 12; ++i) {
        nest += "{{with $.o}}";
    }
    nest += "{{.a}}";
    for (int i = 0; i < 12; ++i) {
        nest += "{{end}}";
    }
    auto deep = txt::stencil::parse(string(nest.data(), nest.size()));
    ASSERT_TRUE(deep.has_value());
    auto od = txt::object{{"o", txt::object{{"a", "z"}}}};
    EXPECT_EQ(deep->render(od), "z");

    // Every depth across the boundary, since the two roads are two calls
    // now and the room one of them hands over is sized from _depth: one
    // block too few and the walk writes past the end of it. Ranges,
    // withs, and the two wrapped in ifs, which count towards the depth
    // without keeping anything of their own.
    auto rows = txt::object{{"xs", txt::list{1}}, {"o", txt::object{{"a", "z"}}},
                            {"m", txt::object{{"k", 1}}}, {"on", true}};
    for (int n = 1; n <= 8; ++n) {
        struct { const char* open; const char* body; const char* want; } shapes[] = {
            {"{{range $.xs}}", "x", "x"},
            {"{{with $.o}}", "{{.a}}", "z"},
            {"{{range $.m}}", "{{.key}}", "k"},
            {"{{if $.on}}{{range $.xs}}", "x", "x"},
            {"{{if $.on}}{{with $.o}}", "{{.a}}", "z"},
        };
        for (auto& shape : shapes) {
            std::string src, shut;
            int per = std::string(shape.open).find("{{if") == 0 ? 2 : 1;
            for (int i = 0; i < n; ++i) {
                src += shape.open;
                for (int k = 0; k < per; ++k) {
                    shut += "{{end}}";
                }
            }
            src += shape.body;
            src += shut;
            auto one = txt::stencil::parse(string(src.data(), src.size()));
            ASSERT_TRUE(one.has_value()) << src;
            EXPECT_EQ(one->render(rows), shape.want) << " at " << n << " deep: " << src;
        }
    }
}

TEST(StencilTest, WhiteSpaceIsTakenAwayOnEitherSide) {
    auto data = txt::object{{"n", 1}, {"on", true}};
    EXPECT_EQ(render("a \t\n {{- n}}", data), "a1");
    EXPECT_EQ(render("{{n -}} \t\n b", data), "1b");
    EXPECT_EQ(render("a\n{{- if on -}}\n  x\n{{- end -}}\nb", data), "axb");
    // A minus with nothing between it and what it stands on is a sign
    EXPECT_EQ(render("{{ .no | default -5}}", data), "-5");
    // and one on its own with a space is the trim
    EXPECT_EQ(render("x   {{- n}}", data), "x1");
}

TEST(StencilTest, ACommentWritesNothingAndHidesWhatIsInIt) {
    auto data = txt::object{{"n", 1}};
    EXPECT_EQ(render("a{{/* }} {{ nonsense */}}b", data), "ab");
    EXPECT_EQ(render("a  {{- /* x */ -}}  b", data), "ab");
    EXPECT_EQ(render("{{/**/}}", data), "");
}

TEST(StencilTest, BracesInsideALiteralDoNotCloseTheAction) {
    auto data = txt::object{{"s", ""}};
    EXPECT_EQ(render("{{.s | default \"a}}b\"}}", data), "a}}b");
    EXPECT_EQ(render("{{.s | default \"a|b\"}}", data), "a|b");
    EXPECT_EQ(render("{{.s | default \"a:b\"}}", data), "a:b");
}

//------------------------------------------------------------------------------
// Read once, written many times
//------------------------------------------------------------------------------
TEST(StencilTest, ASourceIsReadOnceAndWrittenOverAndOver) {
    auto t = txt::stencil::parse(string("{{name}} has {{n}}"));
    ASSERT_TRUE(t.has_value());
    for (int i = 0; i < 100; ++i) {
        auto data = txt::object{{"name", "ada"}, {"n", i}};
        EXPECT_EQ(t->render(data), txt::format("ada has {}", i));
    }
}

TEST(StencilTest, APageOfTextIsOneStepAndNotAThousand) {
    // A run of literal text between two actions is written down whole,
    // as the literal run of a format pattern is
    std::string big(40000, 'x');
    auto t = txt::stencil::parse(string(big.data(), big.size()));
    ASSERT_TRUE(t.has_value());
    EXPECT_EQ(t->steps(), 1u);

    auto two = txt::stencil::parse(string("aaaa{{n}}bbbb"));
    ASSERT_TRUE(two.has_value());
    EXPECT_EQ(two->steps(), 3u);
}

TEST(StencilTest, RenderToSaysWhatTheWholeWouldHaveTaken) {
    // The contract format_to has: what fits is written, and the whole
    // size comes back whether or not it fitted
    auto t = txt::stencil::parse(string("{{a}}-{{b}}"));
    ASSERT_TRUE(t.has_value());
    auto data = txt::object{{"a", "hello"}, {"b", "world"}};

    size_t whole = t->render_to(slice<char>(nullptr, size_t(0)), data);
    EXPECT_EQ(whole, 11u);

    char room[64];
    EXPECT_EQ(t->render_to(slice<char>(room, sizeof room), data), 11u);
    EXPECT_EQ(std::string(room, 11), "hello-world");

    char tight[5];
    EXPECT_EQ(t->render_to(slice<char>(tight, sizeof tight), data), 11u);
    EXPECT_EQ(std::string(tight, 5), "hello");
}

TEST(StencilTest, APageLongerThanTheRoomOnTheStackIsStillWrittenWhole) {
    // render keeps a kilobyte on the stack and takes more when the page
    // runs off the end of it, writing the one step that did not fit
    // again; what is carried over must be exactly what stood there
    auto t = txt::stencil::parse(string("{{range xs}}{{.}},{{end}}"));
    ASSERT_TRUE(t.has_value());
    vector<txt::value> many;
    std::string want;
    for (int i = 0; i < 2000; ++i) {
        many.push_back(txt::value(i));
        want += std::to_string(i);
        want += ',';
    }
    auto data = txt::object{{"xs", txt::list(many)}};
    auto page = t->render(data);
    EXPECT_GT(page.size(), 1024u);
    EXPECT_EQ(std::string(page.data(), page.size()), want);
}

TEST(StencilTest, EveryLengthAroundTheRoomOnTheStackComesOutWhole) {
    // The room doubles, so what is worth walking is every length either
    // side of where it does: a page that ends one character short of the
    // kilobyte, on it, one past it, and the same about two kilobytes and
    // four. Each one is written a character at a time by a loop, so the
    // step that runs off the end is a different step every round, and
    // render_to is asked the same question to say that both roads agree.
    auto t = txt::stencil::parse(string("{{range xs}}x{{end}}"));
    ASSERT_TRUE(t.has_value());
    for (size_t n = 1000; n <= 4100; ++n) {
        if (n > 1060 && n < 2020) {
            n = 2020;
        } else if (n > 2080 && n < 4060) {
            n = 4060;
        }
        vector<txt::value> many;
        for (size_t i = 0; i < n; ++i) {
            many.push_back(txt::value(1));
        }
        auto data = txt::object{{"xs", txt::list(many)}};
        auto page = t->render(data);
        ASSERT_EQ(page.size(), n);
        EXPECT_EQ(std::string(page.data(), page.size()), std::string(n, 'x'));
        EXPECT_EQ(t->render_to(slice<char>(nullptr, size_t(0)), data), n);
    }
}

TEST(StencilTest, OneStepBiggerThanEveryDoublingIsWrittenAllTheSame) {
    // Doubling the room is not enough when a single step is forty
    // kilobytes and the room is one: it has to be made big enough for
    // that step and not merely bigger, or the same step runs off the end
    // for ever. A run of literal text is one step (steps() says so
    // above), and so is a string written through a pipeline.
    std::string big(40000, 'x');
    auto t = txt::stencil::parse(string(big.data(), big.size()));
    ASSERT_TRUE(t.has_value());
    ASSERT_EQ(t->steps(), 1u);
    auto page = t->render(txt::object{});
    EXPECT_EQ(page.size(), big.size());
    EXPECT_EQ(std::string(page.data(), page.size()), big);

    auto piped = txt::stencil::parse(string("{{ s | upper }}"));
    ASSERT_TRUE(piped.has_value());
    auto data = txt::object{{"s", string(big.data(), big.size())}};
    auto through = piped->render(data);
    EXPECT_EQ(through.size(), big.size());
    EXPECT_EQ(std::string(through.data(), through.size()), std::string(40000, 'X'));
}

TEST(StencilTest, ALiteralRunTooBigForTheRoomIsCarriedOverFromWhereItBegan) {
    // A literal run says how long it is before it is written, and the
    // step asks for room after writing all the same, so what it asks
    // for is the size it came to and where it began is that size less
    // the run. The arithmetic only shows when the run begins somewhere
    // other than the front of the page and is longer than a doubling
    // would give it: two runs of forty kilobytes, one either side of a
    // value, so that the second begins at a mark that is not round and
    // what stands before it has already been carried over once.
    std::string big(40000, 'x');
    std::string other(40000, 'y');
    auto t = txt::stencil::parse(string("head-") +
                                 string(big.data(), big.size()) +
                                 string("{{ v }}") +
                                 string(other.data(), other.size()) +
                                 string("-tail"));
    ASSERT_TRUE(t.has_value());
    auto data = txt::object{{"v", string("MIDDLE")}};
    std::string want = "head-" + big + "MIDDLE" + other + "-tail";
    auto page = t->render(data);
    ASSERT_EQ(page.size(), want.size());
    EXPECT_EQ(std::string(page.data(), page.size()), want);
    // The road that cannot take more room says the same number
    EXPECT_EQ(t->render_to(slice<char>(nullptr, size_t(0)), data), want.size());
}

TEST(StencilTest, AStepWrittenAgainIsWrittenOnceAndNotTwice) {
    // The step that did not fit is written over again, which means a
    // function of the pipeline is called a second time for that one
    // step. It must be that step and not the page: a template with a
    // thousand fields in it, each through a function that counts its
    // calls, has one call an element and a handful over — never two
    // thousand.
    long calls = 0;
    txt::stencil_functions fs;              // starts with the six
    fs.add("tally", [&calls](const txt::value& v, slice<const txt::value>) {
        ++calls;
        return v;
    });
    auto t = txt::stencil::parse(string("{{range xs}}{{. | tally}},{{end}}"), fs);
    ASSERT_TRUE(t.has_value());
    vector<txt::value> many;
    std::string want;
    for (int i = 0; i < 1000; ++i) {
        many.push_back(txt::value(i));
        want += std::to_string(i);
        want += ',';
    }
    auto data = txt::object{{"xs", txt::list(many)}};
    auto page = t->render(data);
    EXPECT_GT(page.size(), 1024u);
    EXPECT_EQ(std::string(page.data(), page.size()), want);
    // One a field, and one more for each time the room ran out. The page
    // comes to 3890 characters, so the kilobyte doubles twice and the
    // count is 1002 — bounded rather than fixed, because the room render
    // starts with is its own business, but nothing like two thousand
    EXPECT_GE(calls, 1000);
    EXPECT_LT(calls, 1010);
}

//------------------------------------------------------------------------------
// A source nobody meant
//------------------------------------------------------------------------------
TEST(StencilTest, ASourceThatIsNotATemplateIsRefusedWithAPlaceAndAReason) {
    struct Case {
        const char* source;
        const char* reason;
    };
    const Case cases[] = {
        {"{{ a",                    "the action is not closed"},
        {"{{ if a }}x",             "a block was left open"},
        {"{{ range a }}x",          "a block was left open"},
        {"{{ with a }}x",           "a block was left open"},
        {"x{{ end }}",              "an end with nothing open"},
        {"x{{ else }}y",            "an else with nothing open"},
        {"{{ if a }}x{{ else }}y{{ else }}z{{ end }}", "a second else"},
        {"{{ }}",                   "an empty action"},
        {"{{ a. }}",                "a name was expected after the dot"},
        {"{{ a | }}",               "the name of a function was expected"},
        {"{{ a upper }}",           "a bar was expected between a value and a function"},
        {"{{ a | nosuch }}",        "no function of that name"},
        {"{{ /* x }}",              "the comment is not closed"},
        // A quotation left open is caught by the scan for the end of the
        // action rather than by the reading of the text, and the scan
        // has the better answer: it walks quotes too, so the {{ }} that
        // looked like the end of the action is inside the text and the
        // action really does run off the end of the source
        {"{{ \"x }}",               "the action is not closed"},
        {"{{ 'x }}",                "the action is not closed"},
        {"{{ a:>>>> }}",            "that is not a specification"},
        {"{{ range a }}{{ else if b }}x{{ end }}", "only an if may be chained with else if"},
        {"{{ else zzz }}",          "an else with nothing open"},
    };
    for (auto& c : cases) {
        auto why = refusal(c.source);
        if (!why) {
            ADD_FAILURE() << "was accepted: " << c.source;
            continue;
        }
        EXPECT_EQ(why->message(), c.reason) << "over: " << c.source;
        EXPECT_GE(why->line(), 1u);
        EXPECT_GE(why->column(), 1u);
    }
}

TEST(StencilTest, TheLineAndColumnPointAtTheTrouble) {
    auto why = refusal("all fine here\nand here\n{{ end }}\n");
    ASSERT_TRUE(why);
    EXPECT_EQ(why->line(), 3u);
    EXPECT_EQ(why->column(), 4u);
    EXPECT_EQ(why->offset(), 26u);   // the "end", on the third line's fourth column
    EXPECT_EQ(why->message(), "an end with nothing open");
}

TEST(StencilTest, ParsesAnswersWithoutKeepingAnything) {
    EXPECT_TRUE(txt::stencil::parses(string("{{ a }}{{ if b }}x{{ end }}")));
    EXPECT_FALSE(txt::stencil::parses(string("{{ if b }}x")));
}

TEST(StencilTest, TooManyArgumentsToOneFunctionIsRefused) {
    auto why = refusal("{{ a | default 1 2 3 4 5 6 7 8 9 }}");
    ASSERT_TRUE(why);
    EXPECT_EQ(why->message(), "too many arguments to one function");
    // and the most it takes is still accepted
    EXPECT_TRUE(txt::stencil::parses(string("{{ a | default 1 2 3 4 5 6 7 8 }}")));
}

//------------------------------------------------------------------------------
// The fuzzer. This is code that reads somebody else's file, so it is
// covered the way such code is covered here: a great many sources nobody
// meant, every one of them either refused with a reason or rendered
// without a crash. Under the address and the undefined behaviour
// sanitizers this is what says the parser never walks off its input.
//------------------------------------------------------------------------------
TEST(StencilTest, TheParserSurvivesWhateverItIsGiven) {
    // The pieces a template is made of, so that the noise looks enough
    // like a template to reach the interesting roads: pure random bytes
    // are refused in the first character and test nothing
    static const char* const pieces[] = {
        "{{", "}}", "{{-", "-}}", "{{/*", "*/}}", "{{ ", " }}",
        ".", "..", "$", "$.", "|", ":", "::", "-", "\"", "'", "\\",
        "if", "else", "end", "range", "with", "else if",
        "a", "b", "user.name", "x.y.z", "_n",
        "upper", "lower", "title", "trim", "escape_html", "default",
        ">8.2f", "*^10", "?", "#x", ".3", "n", "s", "d",
        "\"text\"", "'c'", "42", "-7", "1.5", "true",
        "text ", "\n", "\t", " ", "}", "{", "\xc5\xbc", "\xff",
    };
    constexpr size_t piece_count = sizeof(pieces) / sizeof(pieces[0]);

    auto data = oracle_data();
    std::mt19937 rng(20260923);
    std::uniform_int_distribution<size_t> which(0, piece_count - 1);
    std::uniform_int_distribution<size_t> pieces_per_round(1, 24);

    size_t parsed = 0;
    size_t rounds = 20000;
    for (size_t r = 0; r < rounds; ++r) {
        std::string source;
        size_t n = pieces_per_round(rng);
        for (size_t i = 0; i < n; ++i) {
            source += pieces[which(rng)];
        }
        auto t = txt::stencil::parse(string(source.data(), source.size()));
        if (!t) {
            // A refusal must say something and must point inside the
            // source: a reason of nothing, or an offset past the end,
            // would mean a road that forgot to fill it in
            EXPECT_FALSE(t.error().message().empty()) << "over: " << source;
            EXPECT_LE(t.error().offset(), source.size()) << "over: " << source;
            EXPECT_GE(t.error().line(), 1u);
            continue;
        }
        ++parsed;
        // Rendered both ways: into a buffer that cannot hold it, which
        // is the road that counts and never takes more room, and into
        // one that grows until it does
        char tight[8];
        (void)t->render_to(slice<char>(tight, sizeof tight), data);
        auto page = t->render(data);
        (void)page.size();
    }
    // If nothing ever parsed, the loop above asked the renderer nothing
    // at all and the whole test is a parser test by accident
    EXPECT_GT(parsed, rounds / 100) << "the noise never looked like a template";
}

TEST(StencilTest, TheRendererSurvivesDataOfTheWrongShape) {
    // A source that is a perfectly good template, over data that is not
    // what it expects: every road has to be total
    const char* sources[] = {
        "{{range a}}{{.}}{{end}}",
        "{{with a}}{{.b}}{{end}}",
        "{{if a}}{{a.b.c}}{{end}}",
        "{{a.b.c.d.e}}",
        "{{a:>8.2f}}",
        "{{a | upper | trim | default \"x\"}}",
        "{{range a}}{{range .}}{{.}}{{end}}{{end}}",
    };
    const txt::value shapes[] = {
        txt::value(),
        txt::value(0),
        txt::value("text"),
        txt::value(1.5),
        txt::value(true),
        txt::list{1, 2},
        txt::object{{"a", 1}},
        txt::object{{"a", txt::list{1, 2}}},
        txt::object{{"a", "text"}},
        txt::object{{"a", txt::object{{"b", txt::list{txt::object{{"c", 1}}}}}}},
    };
    for (auto s : sources) {
        auto t = txt::stencil::parse(string(s));
        ASSERT_TRUE(t.has_value()) << s;
        for (auto& v : shapes) {
            auto page = t->render(v);
            (void)page.size();
        }
    }
}

// A text inside a nested field kept its quotes at one level and lost them
// at the next: the ladder in write_as gave up the type letter before the
// part of the specification meant for elements, and a text has no
// elements, so the '?' a range hands its elements went first. The nested
// part is what a value that holds nothing cannot take, and it goes first
// now; the letter stays, and the list reads one way at every depth.
TEST(StencilTest, ATextInANestedFieldKeepsItsQuotes) {
    using namespace sgcl;
    txt::value v(txt::list{string("ab cd"), txt::value(txt::list{string("ab cd"), 7})});
    EXPECT_EQ(txt::format("{}", v), string("[\"ab cd\", [\"ab cd\", 7]]"));
    EXPECT_EQ(txt::format("{:>2:>2}", v), string("[\"ab cd\", [\"ab cd\", 7]]"));
    EXPECT_EQ(txt::format("{:>2:>2:>2}", v), string("[\"ab cd\", [\"ab cd\",  7]]"));
    // and a value that is not a range still drops the nested part, as the
    // page says it does: {{ n::>4 }} is the number, not the number padded
    auto t = txt::stencil::parse(string("{{ n::>4 }}"));
    ASSERT_TRUE(t);
    EXPECT_EQ(t->render(txt::object{{"n", 7}}), string("7"));
}
